function createAgentDriver(agentType, options) {
  switch (agentType) {
    case "claude":
      return createClaudeDriver(options);
    case "opencode":
      return new OpenCodeDriver(options);
    case "codex":
      return new CodexDriver(options);
    default:
      throw new Error(`Unknown agent driver: ${agentType}`);
  }
}

